-- 138: equilíbrio de trilhas, lote 3
-- 100 questões novas: 50 de Sustentabilidade e 50 de Inteligência Artificial e Inovação (10 por nível), ids 11787 a 11886.
-- Pode rodar mais de uma vez: usa upsert por id.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[
{"id": 11787, "materia": "sust", "nivel": 0, "enunciado": "Uma garrafa plástica jogada na natureza leva, para se decompor:", "opcoes": ["Centenas de anos", "Poucos dias", "Cerca de uma semana", "Uns dois meses"], "explicacao": "O plástico se decompõe muito devagar e, ao se fragmentar, vira microplástico. Por isso reduzir, reutilizar e reciclar é tão importante."},
{"id": 11788, "materia": "sust", "nivel": 0, "enunciado": "A energia gerada nas usinas hidrelétricas vem:", "opcoes": ["Da força da água dos rios", "Da queima de carvão mineral", "Do calor do interior da Terra", "Da luz do sol captada em placas"], "explicacao": "A água represada movimenta turbinas ligadas a geradores. Carvão é usado nas termelétricas; o calor da Terra, na geotérmica; o sol, na solar."},
{"id": 11789, "materia": "sust", "nivel": 0, "enunciado": "Trocar lâmpadas comuns por lâmpadas de LED ajuda a:", "opcoes": ["Gastar menos energia elétrica", "Aumentar bastante o valor da conta de luz", "Deixar a casa mais quente no verão", "Gastar mais água no banho"], "explicacao": "O LED consome menos energia para iluminar o mesmo ambiente e dura mais tempo."},
{"id": 11790, "materia": "sust", "nivel": 0, "enunciado": "Guardar a água da chuva em cisternas para lavar o quintal é uma atitude que:", "opcoes": ["Economiza água tratada", "Desperdiça água potável", "Polui os rios da cidade", "Aumenta o lixo da casa"], "explicacao": "A água da chuva serve para usos que não exigem água potável, como limpeza e rega, poupando a água tratada."},
{"id": 11791, "materia": "sust", "nivel": 0, "enunciado": "A maior floresta tropical do mundo, que ocupa boa parte do Norte do Brasil, é a:", "opcoes": ["Floresta Amazônica", "Mata Atlântica", "Caatinga", "Floresta Negra"], "explicacao": "A Amazônia se estende por nove países, e a maior parte dela fica no Brasil."},
{"id": 11792, "materia": "sust", "nivel": 0, "enunciado": "Comprar só o que vai usar e evitar o desperdício de comida é aplicar o R de:", "opcoes": ["Reduzir", "Reciclar", "Reutilizar", "Recuperar"], "explicacao": "Reduzir é consumir menos e gerar menos lixo. É o primeiro e mais importante dos 3 Rs."},
{"id": 11793, "materia": "sust", "nivel": 0, "enunciado": "Jogar lixo na rua pode causar, em dias de chuva:", "opcoes": ["Entupimento de bueiros e enchentes", "Mais água limpa chegando às torneiras das casas", "Ar mais puro na cidade", "Menos mosquitos dentro das casas e escolas"], "explicacao": "O lixo arrastado pela chuva entope bueiros e galerias, o que favorece alagamentos e doenças."},
{"id": 11794, "materia": "sust", "nivel": 0, "enunciado": "Doar roupas que você não usa mais, em vez de jogá-las fora, é um exemplo de:", "opcoes": ["Reutilização", "Desmatamento", "Desperdício", "Poluição do ar"], "explicacao": "Reutilizar é dar nova vida a um objeto sem transformá-lo industrialmente."},
{"id": 11795, "materia": "sust", "nivel": 0, "enunciado": "Os carros movidos a gasolina e a diesel contribuem para o aquecimento global porque:", "opcoes": ["Liberam gás carbônico na queima", "Consomem muita água para funcionar todos os dias", "Produzem lixo orgânico nas ruas", "Esfriam o ar das grandes cidades durante a noite"], "explicacao": "A queima de combustíveis fósseis libera CO₂, um dos principais gases de efeito estufa."},
{"id": 11796, "materia": "sust", "nivel": 0, "enunciado": "Uma pessoa que leva sua própria caneca para o trabalho, em vez de usar copos descartáveis, está:", "opcoes": ["Diminuindo a geração de lixo", "Aumentando o consumo de plástico", "Desperdiçando água à toa", "Prejudicando a reciclagem"], "explicacao": "Cada copo descartável que deixa de ser usado é menos lixo produzido."},
{"id": 11797, "materia": "sust", "nivel": 1, "enunciado": "O ODS 15 da Agenda 2030 trata de:", "opcoes": ["Vida terrestre", "Vida na água", "Educação de qualidade", "Trabalho decente"], "explicacao": "O ODS 15 busca proteger e recuperar os ecossistemas terrestres, combater a desertificação e deter a perda de biodiversidade. A vida na água é o ODS 14."},
{"id": 11798, "materia": "sust", "nivel": 1, "enunciado": "O ODS 11 da Agenda 2030 trata de:", "opcoes": ["Cidades e comunidades sustentáveis", "Erradicação da pobreza", "Energia limpa e acessível", "Igualdade de gênero"], "explicacao": "O ODS 11 busca tornar as cidades inclusivas, seguras, resilientes e sustentáveis."},
{"id": 11799, "materia": "sust", "nivel": 1, "enunciado": "O ODS 2 da Agenda 2030 tem como tema:", "opcoes": ["Fome zero e agricultura sustentável", "Saúde e bem-estar", "Água potável e saneamento", "Redução das desigualdades"], "explicacao": "O ODS 1 é a erradicação da pobreza; o ODS 3, saúde e bem-estar; o ODS 6, água e saneamento; o ODS 10, redução das desigualdades."},
{"id": 11800, "materia": "sust", "nivel": 1, "enunciado": "O etanol de cana-de-açúcar é considerado um combustível:", "opcoes": ["Renovável, de origem vegetal", "Fóssil, como o petróleo", "Nuclear, de origem mineral", "Não renovável, como o carvão"], "explicacao": "Biocombustíveis vêm de biomassa que pode ser replantada. O CO₂ liberado na queima é em parte reabsorvido pelo próximo plantio."},
{"id": 11801, "materia": "sust", "nivel": 1, "enunciado": "A pegada ecológica é um indicador que mede:", "opcoes": ["A área produtiva necessária para sustentar o consumo humano", "A quantidade de passos que uma pessoa dá por dia em parques e áreas verdes", "O número de árvores plantadas por município", "A distância percorrida pelos produtos da fábrica até o supermercado"], "explicacao": "A pegada ecológica compara a demanda humana por recursos com a capacidade do planeta de regenerá-los."},
{"id": 11802, "materia": "sust", "nivel": 1, "enunciado": "Biodiversidade significa:", "opcoes": ["A variedade de seres vivos e de ecossistemas", "A quantidade de lixo produzido nas áreas rurais de um país", "O conjunto de rios de uma região", "O total de chuvas registradas em uma região ao longo de um ano"], "explicacao": "A biodiversidade inclui a diversidade de espécies, de genes e de ecossistemas."},
{"id": 11803, "materia": "sust", "nivel": 1, "enunciado": "O selo Procel, colado em eletrodomésticos no Brasil, indica:", "opcoes": ["Os equipamentos mais eficientes no uso de energia", "Os produtos fabricados exclusivamente com material reciclado", "Os aparelhos que funcionam sem eletricidade", "Os produtos importados que têm isenção de imposto de importação"], "explicacao": "O Selo Procel identifica os equipamentos mais eficientes de cada categoria, ajudando o consumidor a gastar menos energia."},
{"id": 11804, "materia": "sust", "nivel": 1, "enunciado": "Na compostagem, os restos de alimentos e folhas se transformam em adubo pela ação de:", "opcoes": ["Microrganismos que decompõem a matéria orgânica", "Produtos químicos adicionados pela prefeitura no lixo recolhido das casas", "Altas temperaturas de fornos industriais", "Raios ultravioleta emitidos por lâmpadas especiais instaladas nos aterros"], "explicacao": "Bactérias e fungos decompõem a matéria orgânica, gerando um composto rico em nutrientes."},
{"id": 11805, "materia": "sust", "nivel": 1, "enunciado": "Consumo consciente é:", "opcoes": ["Escolher produtos pensando nos impactos sociais e ambientais", "Comprar sempre a versão mais cara de cada produto disponível no mercado", "Evitar qualquer tipo de compra durante o ano", "Trocar de celular sempre que a fabricante lança um modelo novo no mercado"], "explicacao": "Consumir com consciência envolve comprar o necessário, preferir produtos duráveis e de origem responsável e descartar corretamente."},
{"id": 11806, "materia": "sust", "nivel": 1, "enunciado": "A energia eólica é considerada limpa porque:", "opcoes": ["Não emite gases de efeito estufa ao gerar eletricidade", "Não precisa de nenhum tipo de equipamento ou estrutura para ser gerada", "Funciona apenas nas noites sem vento", "É produzida a partir da queima de madeira e de resíduos agrícolas"], "explicacao": "As turbinas usam a força dos ventos. O Nordeste brasileiro concentra a maior parte dos parques eólicos do país."},
{"id": 11807, "materia": "sust", "nivel": 2, "enunciado": "Pelo Código Florestal (Lei 12.651/2012), o Cadastro Ambiental Rural (CAR) é:", "opcoes": ["Um registro eletrônico obrigatório para todos os imóveis rurais", "Uma licença ambiental que autoriza desmatar até 20% da área da propriedade", "Um imposto cobrado sobre áreas de floresta", "Um cadastro facultativo, exigido apenas das grandes fazendas exportadoras"], "explicacao": "O CAR integra informações ambientais das propriedades rurais e serve de base para controle, monitoramento e planejamento ambiental."},
{"id": 11808, "materia": "sust", "nivel": 2, "enunciado": "Pelo Código Florestal, a faixa mínima de Área de Preservação Permanente às margens de cursos d'água com menos de 10 metros de largura é de:", "opcoes": ["30 metros", "5 metros", "100 metros", "500 metros"], "explicacao": "Art. 4º, I, a, da Lei 12.651/2012. A faixa aumenta conforme a largura do rio, até 500 metros para rios com mais de 600 metros."},
{"id": 11809, "materia": "sust", "nivel": 2, "enunciado": "Pelo Código Florestal, a Reserva Legal de imóvel situado em área de cerrado na Amazônia Legal deve ser de, no mínimo:", "opcoes": ["35%", "20%", "50%", "80%"], "explicacao": "Art. 12, I, b, da Lei 12.651/2012. Na Amazônia Legal: 80% em floresta, 35% em cerrado e 20% em campos gerais. Nas demais regiões, 20%."},
{"id": 11810, "materia": "sust", "nivel": 2, "enunciado": "Pela Política Nacional de Recursos Hídricos (Lei 9.433/1997), em situações de escassez, o uso prioritário da água é:", "opcoes": ["O consumo humano e a dessedentação de animais", "A irrigação de grandes lavouras", "A geração de energia hidrelétrica", "O abastecimento das indústrias"], "explicacao": "Art. 1º, III, da Lei 9.433/1997. A lei também define a bacia hidrográfica como unidade territorial de gestão."},
{"id": 11811, "materia": "sust", "nivel": 2, "enunciado": "Pela Lei 9.433/1997, a gestão dos recursos hídricos deve ser:", "opcoes": ["Descentralizada e participativa", "Exclusiva da União, sem participação dos usuários nem da sociedade civil", "Feita apenas pelas empresas de saneamento", "Restrita aos municípios banhados por rios federais e estaduais"], "explicacao": "Art. 1º, VI, da Lei 9.433/1997. Os comitês de bacia são o principal espaço dessa participação."},
{"id": 11812, "materia": "sust", "nivel": 2, "enunciado": "Pela Política Nacional de Resíduos Sólidos, rejeito é:", "opcoes": ["O resíduo que, esgotados o tratamento e a recuperação, só pode ter disposição final", "Qualquer material que possa ser reciclado por cooperativas de catadores", "O resíduo orgânico destinado à compostagem", "A embalagem devolvida ao fabricante por meio da logística reversa obrigatória"], "explicacao": "Art. 3º, XV, da Lei 12.305/2010. A disposição final ambientalmente adequada dos rejeitos é feita em aterros."},
{"id": 11813, "materia": "sust", "nivel": 2, "enunciado": "A Política Nacional de Resíduos Sólidos proíbe, como forma de destinação de resíduos:", "opcoes": ["O lançamento a céu aberto, como nos lixões", "A reciclagem feita por cooperativas", "A compostagem de resíduos orgânicos", "A disposição de rejeitos em aterro sanitário"], "explicacao": "Art. 47, II, da Lei 12.305/2010. Também é proibida a queima a céu aberto ou em instalações não licenciadas."},
{"id": 11814, "materia": "sust", "nivel": 2, "enunciado": "Pelo Novo Marco Legal do Saneamento (Lei 14.026/2020), a meta de universalização até 31 de dezembro de 2033 é atender:", "opcoes": ["99% da população com água potável e 90% com esgoto tratado", "100% da população com água tratada e esgoto já até o final de 2025", "50% da população com esgoto tratado até 2040", "80% da população com água potável e 60% com coleta e tratamento de esgoto"], "explicacao": "Art. 11-B da Lei 11.445/2007, com a redação da Lei 14.026/2020."},
{"id": 11815, "materia": "sust", "nivel": 2, "enunciado": "Pela Política Nacional de Educação Ambiental (Lei 9.795/1999), a educação ambiental no ensino formal:", "opcoes": ["Não deve ser, em regra, uma disciplina específica", "Deve ser uma disciplina obrigatória em todas as séries do ensino fundamental", "É proibida nas escolas públicas", "Fica restrita ao ensino superior e aos cursos técnicos profissionalizantes"], "explicacao": "Art. 10, § 1º. Ela deve ser uma prática educativa integrada, contínua e permanente, em todos os níveis e modalidades."},
{"id": 11816, "materia": "sust", "nivel": 2, "enunciado": "O licenciamento ambiental de empreendimentos é, tradicionalmente, feito em três etapas, com as licenças:", "opcoes": ["Prévia, de Instalação e de Operação", "Inicial, Parcial e Final", "Municipal, Estadual e Federal", "Provisória, Temporária e Definitiva"], "explicacao": "Res. Conama 237/1997: a LP aprova a localização e a concepção; a LI autoriza a instalação; a LO autoriza o funcionamento."},
{"id": 11817, "materia": "sust", "nivel": 3, "enunciado": "Pela Política Nacional de Resíduos Sólidos, é princípio que reconhece quem protege o meio ambiente como merecedor de recompensa o:", "opcoes": ["Protetor-recebedor", "Poluidor-pagador", "Usuário-pagador", "Da prevenção"], "explicacao": "Art. 6º, II, da Lei 12.305/2010 lista o poluidor-pagador e o protetor-recebedor. Este último fundamenta, por exemplo, o pagamento por serviços ambientais."},
{"id": 11818, "materia": "sust", "nivel": 3, "enunciado": "Pela Lei 9.605/1998, poderá ser desconsiderada a pessoa jurídica:", "opcoes": ["Sempre que sua personalidade for obstáculo ao ressarcimento do dano ambiental", "Apenas se houver fraude comprovada por perícia contábil determinada pelo juiz", "Somente quando a empresa for estrangeira", "Apenas após o trânsito em julgado da condenação penal dos seus sócios e diretores"], "explicacao": "Art. 4º da Lei 9.605/1998, que adota a chamada teoria menor da desconsideração."},
{"id": 11819, "materia": "sust", "nivel": 3, "enunciado": "Na estrutura do Sisnama (Lei 6.938/1981), o Conama é o órgão:", "opcoes": ["Consultivo e deliberativo", "Executor federal", "Superior, de assessoramento do Presidente", "Local, de cada município"], "explicacao": "O órgão superior é o Conselho de Governo; os executores federais são o Ibama e o ICMBio; os órgãos seccionais são os estaduais; os locais, os municipais."},
{"id": 11820, "materia": "sust", "nivel": 3, "enunciado": "No SNUC (Lei 9.985/2000), é exemplo de unidade de conservação de uso sustentável:", "opcoes": ["Reserva Extrativista", "Estação Ecológica", "Reserva Biológica", "Parque Nacional"], "explicacao": "As de uso sustentável incluem APA, Floresta Nacional, Reserva Extrativista, Reserva de Desenvolvimento Sustentável e RPPN. As demais alternativas são de proteção integral."},
{"id": 11821, "materia": "sust", "nivel": 3, "enunciado": "No SNUC, a Reserva Particular do Patrimônio Natural (RPPN) é:", "opcoes": ["Área privada, gravada com perpetuidade, para conservar a biodiversidade", "Área pública destinada à exploração madeireira por empresas concessionárias", "Terra indígena demarcada pela União", "Área temporária, que pode ser desfeita a qualquer momento pelo proprietário"], "explicacao": "Art. 21 da Lei 9.985/2000. O gravame é averbado no registro do imóvel."},
{"id": 11822, "materia": "sust", "nivel": 3, "enunciado": "São instrumentos da Política Nacional de Recursos Hídricos, entre outros:", "opcoes": ["A outorga e a cobrança pelo uso da água", "A privatização dos rios e a venda das nascentes a empresas de saneamento", "O tombamento das bacias e a desapropriação de lagos", "A isenção de tarifas para indústrias e a proibição de irrigação no semiárido"], "explicacao": "Art. 5º da Lei 9.433/1997: planos de recursos hídricos, enquadramento dos corpos d'água, outorga, cobrança e sistema de informações."},
{"id": 11823, "materia": "sust", "nivel": 3, "enunciado": "Pela Lei 9.605/1998, nos crimes ambientais de menor potencial ofensivo, a transação penal só pode ser proposta se houver:", "opcoes": ["Prévia composição do dano ambiental, salvo impossibilidade", "Confissão formal do crime perante o delegado, na presença de advogado", "Pagamento de multa de 100 salários mínimos", "Autorização expressa do órgão ambiental federal, ouvido o Ministério Público"], "explicacao": "Art. 27 da Lei 9.605/1998."},
{"id": 11824, "materia": "sust", "nivel": 3, "enunciado": "Na logística reversa da Política Nacional de Resíduos Sólidos, o acordo setorial é:", "opcoes": ["O ato contratual entre o poder público e fabricantes, importadores, distribuidores ou comerciantes", "Uma multa aplicada às empresas que poluem acima dos limites fixados pelo Conama", "Um tratado internacional sobre resíduos", "A licença concedida pelo órgão ambiental para instalar aterros sanitários e usinas"], "explicacao": "Art. 3º, I, da Lei 12.305/2010. O acordo implanta a responsabilidade compartilhada pelo ciclo de vida do produto."},
{"id": 11825, "materia": "sust", "nivel": 3, "enunciado": "A Lei 14.119/2021 (Pagamento por Serviços Ambientais) admite, como modalidade de pagamento, entre outras:", "opcoes": ["Títulos verdes (green bonds) e comodato", "Apenas o pagamento direto em dinheiro", "Somente a isenção do Imposto de Renda", "Exclusivamente a doação de terras públicas"], "explicacao": "Art. 3º da Lei 14.119/2021: pagamento direto, monetário ou não; prestação de melhorias sociais; compensação vinculada a certificado de redução de emissões; títulos verdes; comodato; e Cota de Reserva Ambiental."},
{"id": 11826, "materia": "sust", "nivel": 3, "enunciado": "Pelo Acordo de Paris, os países devem apresentar e atualizar suas contribuições nacionalmente determinadas (NDCs):", "opcoes": ["A cada 5 anos, com metas cada vez mais ambiciosas", "Uma única vez, sem necessidade de revisão", "A cada 20 anos, apenas se houver nova conferência", "Somente quando o país sediar uma COP"], "explicacao": "O acordo também prevê o balanço global (global stocktake), a cada 5 anos, para avaliar o progresso coletivo."},
{"id": 11827, "materia": "sust", "nivel": 4, "enunciado": "Pela Súmula 613 do STJ, em tema de Direito Ambiental:", "opcoes": ["Não se admite a aplicação da teoria do fato consumado", "Aplica-se a teoria do fato consumado após 10 anos de ocupação", "O fato consumado afasta o dever de recuperar a área", "A teoria do fato consumado vale apenas para áreas urbanas"], "explicacao": "O tempo de ocupação irregular não gera direito adquirido de poluir ou de manter a degradação."},
{"id": 11828, "materia": "sust", "nivel": 4, "enunciado": "Pela Súmula 652 do STJ, a responsabilidade civil da Administração Pública por danos ao meio ambiente decorrentes de sua omissão no dever de fiscalização é:", "opcoes": ["Solidária, mas de execução subsidiária", "Exclusiva, afastando a do poluidor direto", "Subjetiva, dependendo de prova de dolo", "Inexistente, por se tratar de omissão"], "explicacao": "A Administração responde junto com o degradador, mas só é cobrada depois do causador direto do dano."},
{"id": 11829, "materia": "sust", "nivel": 4, "enunciado": "Pela LC 140/2011, havendo mais de um auto de infração lavrado sobre a mesma hipótese de dano ambiental, prevalece o auto lavrado pelo:", "opcoes": ["Órgão que detenha a atribuição de licenciamento ou autorização", "Órgão federal, em qualquer caso", "Primeiro órgão que chegar ao local", "Município onde ocorreu o fato"], "explicacao": "Art. 17, § 3º, da LC 140/2011. Os demais entes mantêm a atribuição comum de fiscalização."},
{"id": 11830, "materia": "sust", "nivel": 4, "enunciado": "Pela Lei 9.605/1998, para impor e graduar a penalidade, a autoridade observará, entre outros fatores:", "opcoes": ["A gravidade do fato, os antecedentes e a situação econômica do infrator", "Apenas o valor do lucro obtido com a infração, apurado por perícia contábil", "Somente o número de testemunhas do fato", "Exclusivamente a extensão da área desmatada, medida por imagens de satélite"], "explicacao": "Art. 6º da Lei 9.605/1998: gravidade (motivos e consequências), antecedentes quanto à legislação ambiental e situação econômica."},
{"id": 11831, "materia": "sust", "nivel": 4, "enunciado": "Pela Lei 9.605/1998, é pena restritiva de direitos aplicável à pessoa física:", "opcoes": ["Recolhimento domiciliar", "Dissolução compulsória", "Liquidação forçada", "Intervenção judicial"], "explicacao": "Art. 8º: prestação de serviços à comunidade, interdição temporária de direitos, suspensão parcial ou total de atividades, prestação pecuniária e recolhimento domiciliar."},
{"id": 11832, "materia": "sust", "nivel": 4, "enunciado": "Pela Política Nacional de Resíduos Sólidos, a recuperação energética dos resíduos sólidos urbanos, como a incineração:", "opcoes": ["Pode ser usada, se viável técnica e ambientalmente e com monitoramento de gases", "É totalmente proibida no Brasil desde a edição da Política Nacional de Resíduos", "Tem prioridade sobre a reciclagem e a reutilização", "Dispensa licenciamento ambiental quando feita por consórcio de municípios"], "explicacao": "Art. 9º, § 1º, da Lei 12.305/2010."},
{"id": 11833, "materia": "sust", "nivel": 4, "enunciado": "Pelo Código Florestal, a Cota de Reserva Ambiental (CRA) é:", "opcoes": ["Título que representa área com vegetação nativa e compensa déficit de Reserva Legal", "Imposto pago por quem desmata acima do limite permitido pelo órgão ambiental", "Licença para suprimir vegetação em APP", "Cadastro dos imóveis urbanos que possuem áreas verdes, praças e jardins"], "explicacao": "Art. 44 da Lei 12.651/2012. A CRA pode ser negociada e usada para compensar Reserva Legal no mesmo bioma."},
{"id": 11834, "materia": "sust", "nivel": 4, "enunciado": "Pela Constituição, incumbe ao Poder Público, para assegurar o meio ambiente ecologicamente equilibrado, controlar a produção, a comercialização e o emprego de técnicas, métodos e substâncias que:", "opcoes": ["Comportem risco para a vida e o meio ambiente", "Tenham sido produzidos fora do território nacional e importados sem licença", "Sejam comercializados por empresas estatais", "Dependam de patente registrada no INPI e ainda não tenham sido testados"], "explicacao": "Art. 225, § 1º, V, da CF."},
{"id": 11835, "materia": "sust", "nivel": 4, "enunciado": "Pela Constituição, aquele que explorar recursos minerais fica obrigado a:", "opcoes": ["Recuperar o meio ambiente degradado, conforme exigido pelo órgão público", "Pagar apenas os tributos devidos, sem qualquer dever de recuperar a área explorada", "Doar a área degradada ao município", "Recuperar a área somente se houver condenação penal transitada em julgado"], "explicacao": "Art. 225, § 2º, da CF."},
{"id": 11836, "materia": "sust", "nivel": 4, "enunciado": "Pela Constituição, as usinas que operem com reator nuclear:", "opcoes": ["Devem ter a localização definida em lei federal", "Podem ser instaladas livremente por qualquer estado, mediante simples licença ambiental", "Dependem apenas de licença municipal", "São proibidas em todo o território nacional desde a promulgação da Constituição"], "explicacao": "Art. 225, § 6º, da CF. A competência para legislar sobre atividades nucleares é privativa da União (art. 22, XXVI)."},
{"id": 11837, "materia": "ia", "nivel": 0, "enunciado": "Quando o banco bloqueia uma compra estranha no seu cartão, muitas vezes ele usou IA para:", "opcoes": ["Detectar um padrão fora do seu costume", "Escolher o que você pode comprar", "Aumentar o limite do cartão", "Imprimir a fatura do mês"], "explicacao": "Modelos de detecção de fraude comparam cada compra com o histórico do cliente e alertam quando algo foge do padrão."},
{"id": 11838, "materia": "ia", "nivel": 0, "enunciado": "Um carro autônomo é aquele que:", "opcoes": ["Dirige sozinho, com sensores e IA", "Anda apenas com energia solar captada no teto", "Só pode ser dirigido por pilotos profissionais", "Funciona sem nenhum tipo de motor"], "explicacao": "Câmeras, radares e sensores alimentam sistemas de IA que reconhecem a via, os pedestres e os outros veículos."},
{"id": 11839, "materia": "ia", "nivel": 0, "enunciado": "O teclado do celular que sugere a próxima palavra enquanto você digita usa:", "opcoes": ["Previsão de texto com IA", "Uma lista fixa de palavras", "Leitura do seu pensamento", "Uma ligação com a operadora"], "explicacao": "O sistema aprende quais palavras costumam vir em seguida e oferece sugestões."},
{"id": 11840, "materia": "ia", "nivel": 0, "enunciado": "Ao usar uma ferramenta de IA gratuita na internet, é recomendável:", "opcoes": ["Não colocar dados pessoais ou sigilosos", "Informar a senha do banco para agilizar", "Enviar fotos de documentos de terceiros", "Colar dados de processos sigilosos"], "explicacao": "Muitas ferramentas armazenam o que é digitado. Dados pessoais e sigilosos podem vazar ou ser usados sem controle."},
{"id": 11841, "materia": "ia", "nivel": 0, "enunciado": "O aplicativo de mapa que mostra o caminho mais rápido, desviando de engarrafamentos, usa:", "opcoes": ["Dados de trânsito e algoritmos de rota", "Apenas um mapa de papel digitalizado há muitos anos", "A opinião do motorista mais próximo", "Um sorteio entre os caminhos possíveis até o destino"], "explicacao": "O app analisa o trânsito em tempo real e calcula a melhor rota."},
{"id": 11842, "materia": "ia", "nivel": 0, "enunciado": "Ao ver na internet uma foto muito chocante de uma autoridade, que pode ter sido criada por IA, o correto é:", "opcoes": ["Conferir a fonte antes de compartilhar", "Compartilhar logo para avisar todo mundo", "Acreditar, porque foto não mente", "Mandar para os grupos da família"], "explicacao": "Imagens geradas por IA podem ser muito realistas. Verificar a origem evita espalhar desinformação."},
{"id": 11843, "materia": "ia", "nivel": 0, "enunciado": "Transformar a fala de uma pessoa em texto escrito, como na legenda automática de vídeos, é chamado de:", "opcoes": ["Reconhecimento de fala", "Reconhecimento facial", "Impressão digital", "Compressão de arquivos"], "explicacao": "O reconhecimento de fala converte áudio em texto e é muito usado em legendas e assistentes de voz."},
{"id": 11844, "materia": "ia", "nivel": 0, "enunciado": "Nas redes sociais, um “bot” é:", "opcoes": ["Uma conta automatizada por um programa", "Uma pessoa famosa com muitos seguidores nas redes", "Um tipo de vírus que apaga o celular", "O botão usado para curtir uma publicação de um amigo"], "explicacao": "Bots publicam e interagem de forma automática e podem ser usados para espalhar mensagens em massa."},
{"id": 11845, "materia": "ia", "nivel": 0, "enunciado": "O caixa de supermercado que reconhece a fruta pela câmera, sem código de barras, usa:", "opcoes": ["Visão computacional", "Energia eólica", "Código Morse", "Leitura em Braille"], "explicacao": "A visão computacional permite à máquina identificar objetos em imagens."},
{"id": 11846, "materia": "ia", "nivel": 0, "enunciado": "Uma ferramenta de IA deu a resposta de uma questão de concurso. A melhor atitude é:", "opcoes": ["Conferir na lei ou na doutrina se está certa", "Decorar a resposta sem conferir", "Achar que a IA nunca erra em Direito", "Ignorar a lei e confiar só na IA"], "explicacao": "Ferramentas de IA podem errar e até inventar artigos de lei. A conferência na fonte oficial é indispensável."},
{"id": 11847, "materia": "ia", "nivel": 1, "enunciado": "A expressão “inteligência artificial” foi usada pela primeira vez como nome de uma área de pesquisa em:", "opcoes": ["Uma conferência no Dartmouth College, em 1956", "Um artigo de Albert Einstein, em 1905", "O lançamento do primeiro iPhone, em 2007", "A criação da internet comercial, em 1995"], "explicacao": "O termo foi proposto por John McCarthy e colegas para o encontro de Dartmouth, nos Estados Unidos."},
{"id": 11848, "materia": "ia", "nivel": 1, "enunciado": "As redes neurais artificiais foram inspiradas:", "opcoes": ["No funcionamento dos neurônios do cérebro", "Na estrutura das raízes das plantas", "No movimento dos planetas", "Na organização das colmeias de abelhas e dos formigueiros"], "explicacao": "Cada neurônio artificial recebe entradas, aplica pesos e passa o resultado adiante, de forma simplificada."},
{"id": 11849, "materia": "ia", "nivel": 1, "enunciado": "Prever o preço de um imóvel a partir de sua área e localização é uma tarefa de:", "opcoes": ["Regressão", "Classificação", "Agrupamento", "Tradução"], "explicacao": "Regressão prevê um valor numérico contínuo. Classificação atribui uma categoria, como “spam” ou “não spam”."},
{"id": 11850, "materia": "ia", "nivel": 1, "enunciado": "Separar clientes em grupos com perfis parecidos, sem categorias definidas antes, é uma tarefa de:", "opcoes": ["Agrupamento (clusterização)", "Classificação supervisionada", "Tradução automática", "Reconhecimento de fala"], "explicacao": "O agrupamento é típico do aprendizado não supervisionado: o próprio algoritmo encontra os grupos."},
{"id": 11851, "materia": "ia", "nivel": 1, "enunciado": "Uma IA multimodal é aquela que:", "opcoes": ["Trabalha com texto, imagem e áudio, por exemplo", "Funciona em vários países ao mesmo tempo, em vários idiomas", "Tem vários usuários conectados de uma vez", "Só funciona com vários computadores ligados em rede local"], "explicacao": "Modelos multimodais podem, por exemplo, descrever uma foto ou responder perguntas sobre um gráfico."},
{"id": 11852, "materia": "ia", "nivel": 1, "enunciado": "O treinamento de grandes modelos de IA costuma usar, como hardware principal:", "opcoes": ["GPUs, placas de processamento gráfico", "Disquetes de alta capacidade", "Impressoras a laser", "Monitores de alta resolução"], "explicacao": "As GPUs fazem muitos cálculos em paralelo, o que acelera o treinamento de redes neurais."},
{"id": 11853, "materia": "ia", "nivel": 1, "enunciado": "Um modelo de IA “de pesos abertos” é aquele que:", "opcoes": ["Tem seus parâmetros disponíveis para download", "Pode ser usado apenas por órgãos públicos e universidades federais", "Não precisa de dados para ser treinado", "Funciona sem eletricidade"], "explicacao": "Com os pesos disponíveis, outras pessoas podem rodar e ajustar o modelo em seus próprios computadores."},
{"id": 11854, "materia": "ia", "nivel": 1, "enunciado": "Rotular ou marcar conteúdos criados por IA, como imagens e vídeos, serve principalmente para:", "opcoes": ["Informar que o conteúdo é sintético", "Aumentar a qualidade e a resolução da imagem publicada", "Proteger o computador contra vírus", "Deixar o arquivo menor e mais rápido de baixar no celular"], "explicacao": "A rotulagem de conteúdo sintético ajuda a combater a desinformação e os deepfakes."},
{"id": 11855, "materia": "ia", "nivel": 1, "enunciado": "Um assistente virtual que agenda reuniões, responde e-mails e consulta sistemas por conta própria, seguindo um objetivo, é um exemplo de:", "opcoes": ["Agente de IA", "Planilha eletrônica", "Antivírus", "Navegador de internet"], "explicacao": "Agentes de IA planejam e executam ações em várias etapas, usando ferramentas, e não apenas respondem perguntas."},
{"id": 11856, "materia": "ia", "nivel": 1, "enunciado": "Dados sintéticos, em IA, são:", "opcoes": ["Dados gerados artificialmente que imitam os reais", "Dados apagados por engano do sistema", "Dados copiados de redes sociais sem a autorização dos usuários", "Dados impressos em papel reciclado"], "explicacao": "Eles ajudam a treinar modelos quando os dados reais são escassos ou sensíveis, mas podem carregar os vieses dos dados de origem."},
{"id": 11857, "materia": "ia", "nivel": 2, "enunciado": "Pedir ao modelo de linguagem que “pense passo a passo” antes de responder é uma técnica chamada:", "opcoes": ["Cadeia de pensamento (chain of thought)", "Ajuste fino (fine-tuning)", "Compressão de dados", "Aprendizado federado"], "explicacao": "A técnica costuma melhorar o desempenho em problemas de raciocínio, como cálculos e lógica."},
{"id": 11858, "materia": "ia", "nivel": 2, "enunciado": "Pedir a um modelo que execute uma tarefa sem dar nenhum exemplo no prompt é chamado de:", "opcoes": ["Zero-shot", "Few-shot", "Overfitting", "Backpropagation"], "explicacao": "No few-shot, o prompt traz alguns exemplos. No zero-shot, o modelo recebe só a instrução."},
{"id": 11859, "materia": "ia", "nivel": 2, "enunciado": "Num sistema que identifica pessoas procuradas, o falso negativo ocorre quando o sistema:", "opcoes": ["Não reconhece uma pessoa que é procurada", "Aponta como procurada uma pessoa inocente que passou pela câmera", "Reconhece corretamente uma pessoa procurada", "Recusa analisar imagens de baixa qualidade ou com pouca iluminação"], "explicacao": "Falso positivo é apontar um inocente; falso negativo é deixar passar quem deveria ser detectado."},
{"id": 11860, "materia": "ia", "nivel": 2, "enunciado": "O ataque em que alguém insere dados manipulados no conjunto de treinamento para corromper o comportamento do modelo é chamado de:", "opcoes": ["Envenenamento de dados (data poisoning)", "Injeção de prompt", "Phishing", "Força bruta"], "explicacao": "Na injeção de prompt, as instruções maliciosas vêm no momento do uso, e não no treinamento."},
{"id": 11861, "materia": "ia", "nivel": 2, "enunciado": "Pequenas alterações quase invisíveis em uma imagem, feitas para enganar um classificador, são chamadas de:", "opcoes": ["Exemplos adversariais", "Dados rotulados", "Marcas d'água", "Embeddings"], "explicacao": "Uma placa de trânsito com adesivos discretos, por exemplo, pode ser classificada de forma errada."},
{"id": 11862, "materia": "ia", "nivel": 2, "enunciado": "No treinamento de redes neurais, a função de perda (loss) mede:", "opcoes": ["O quanto as previsões se afastam das respostas corretas", "A quantidade de energia elétrica gasta pelo computador durante o treino", "O tempo que o modelo leva para responder", "O número de usuários que usam o sistema ao mesmo tempo em horário de pico"], "explicacao": "O treinamento ajusta os parâmetros para reduzir a perda."},
{"id": 11863, "materia": "ia", "nivel": 2, "enunciado": "O gradiente descendente é um método usado para:", "opcoes": ["Ajustar os parâmetros na direção que reduz o erro", "Apagar dados antigos do servidor para liberar espaço em disco", "Comprimir imagens para a internet", "Criptografar as senhas dos usuários antes de gravá-las no banco"], "explicacao": "A cada passo, os pesos são atualizados no sentido contrário ao gradiente da função de perda."},
{"id": 11864, "materia": "ia", "nivel": 2, "enunciado": "Num conjunto de dados com 98% de transações legítimas e 2% de fraudes, um modelo que sempre responde “legítima” terá:", "opcoes": ["Acurácia de 98%, sem detectar nenhuma fraude", "Acurácia de 2%, com todas as fraudes detectadas corretamente pelo sistema", "Acurácia de 50%, por acaso", "Revocação de 100% para as fraudes e precisão de 98% para as transações"], "explicacao": "Com classes desbalanceadas, a acurácia engana. Métricas como revocação e precisão mostram melhor o desempenho."},
{"id": 11865, "materia": "ia", "nivel": 2, "enunciado": "O underfitting (subajuste) ocorre quando o modelo:", "opcoes": ["É simples demais e não aprende os padrões", "Decora os dados de treino e erra quando recebe exemplos novos", "Fica muito lento para responder", "Usa dados de outra língua, diferente da usada pelos usuários finais"], "explicacao": "No overfitting o modelo decora o treino; no underfitting, ele não aprende o suficiente."},
{"id": 11866, "materia": "ia", "nivel": 2, "enunciado": "Pela LGPD, o tratamento de dados pessoais para treinar um sistema de IA:", "opcoes": ["Exige base legal, como consentimento ou legítimo interesse", "Está liberado, porque a IA não é regulada pela LGPD nem por outra norma", "Só é permitido para empresas estrangeiras", "Dispensa qualquer cuidado se os dados já estiverem publicados na internet"], "explicacao": "A LGPD vale para qualquer tratamento de dados pessoais, inclusive em IA. Mesmo dados públicos exigem finalidade, boa-fé e base legal."},
{"id": 11867, "materia": "ia", "nivel": 3, "enunciado": "A arquitetura Transformer, base dos grandes modelos de linguagem atuais, tem como mecanismo central:", "opcoes": ["A atenção, que relaciona os tokens entre si", "A leitura de cada palavra isoladamente, sem considerar as palavras vizinhas", "Uma tabela fixa de respostas prontas", "A conversão do texto em código de barras para acelerar o processamento"], "explicacao": "Apresentada em 2017 no artigo “Attention Is All You Need”, a arquitetura permite processar sequências em paralelo."},
{"id": 11868, "materia": "ia", "nivel": 3, "enunciado": "Técnicas como regularização e dropout são usadas em redes neurais para:", "opcoes": ["Reduzir o overfitting", "Aumentar o tamanho do conjunto de dados", "Acelerar a internet do usuário", "Traduzir o modelo para outra língua"], "explicacao": "O dropout desliga neurônios aleatoriamente no treino, evitando que a rede dependa demais de poucos caminhos."},
{"id": 11869, "materia": "ia", "nivel": 3, "enunciado": "A validação cruzada (k-fold) consiste em:", "opcoes": ["Dividir os dados em k partes e alternar a de teste", "Treinar o modelo em k computadores diferentes ao mesmo tempo, em paralelo", "Pedir a k pessoas que revisem cada resposta", "Repetir o treino k vezes até atingir 100% de acurácia nos dados de treino"], "explicacao": "A média dos resultados nas k rodadas dá uma estimativa mais confiável do desempenho."},
{"id": 11870, "materia": "ia", "nivel": 3, "enunciado": "Pela Resolução CNJ 615/2025, é considerado de alto risco o uso de IA para:", "opcoes": ["Avaliar provas e sua valoração em processos contenciosos", "Transcrever áudios de audiências com revisão humana", "Classificar petições por assunto", "Resumir documentos com supervisão humana"], "explicacao": "O Anexo de Classificação de Riscos traz como alto risco o perfilamento, a avaliação de provas, o enquadramento de fatos como crimes, as conclusões sobre aplicação de normas a fatos e o reconhecimento biométrico. As demais alternativas são de baixo risco."},
{"id": 11871, "materia": "ia", "nivel": 3, "enunciado": "Pela Resolução CNJ 615/2025, quando o magistrado usa IA generativa contratada diretamente, é vedado inserir na ferramenta:", "opcoes": ["Dados sigilosos, salvo anonimização ou proteção equivalente", "Qualquer texto em língua portuguesa", "Perguntas sobre jurisprudência pública já publicada nos sites dos tribunais", "Modelos de documentos sem dados pessoais das partes ou de terceiros"], "explicacao": "A norma também exige capacitação prévia, uso apenas auxiliar e proibição de uso dos dados pelo fornecedor para treinamento."},
{"id": 11872, "materia": "ia", "nivel": 3, "enunciado": "Pela Lei 14.460/2022, a Autoridade Nacional de Proteção de Dados (ANPD) passou a ser:", "opcoes": ["Autarquia de natureza especial", "Órgão da Presidência da República sem autonomia", "Empresa pública de capital aberto", "Departamento do Ministério da Fazenda"], "explicacao": "A ANPD foi transformada em autarquia de natureza especial, com autonomia técnica e decisória e patrimônio próprio."},
{"id": 11873, "materia": "ia", "nivel": 3, "enunciado": "Pelo AI Act da União Europeia, sistemas como chatbots e geradores de deepfakes estão sujeitos, em regra, a:", "opcoes": ["Obrigações de transparência sobre o uso de IA", "Proibição total de uso em todo o território da União Europeia", "Nenhuma regra, por serem de risco mínimo", "Autorização prévia do Parlamento Europeu para cada sistema colocado no mercado"], "explicacao": "Os sistemas de risco limitado têm deveres de transparência. As práticas de risco inaceitável são proibidas, e as de alto risco têm requisitos rigorosos."},
{"id": 11874, "materia": "ia", "nivel": 3, "enunciado": "O “viés de automação” é:", "opcoes": ["A tendência de confiar demais em sugestões da máquina", "Um defeito físico nos servidores que armazenam os dados de treinamento", "A preferência dos sistemas por trabalhar à noite", "A obrigação legal de automatizar todos os serviços públicos digitais"], "explicacao": "O risco é o servidor ou o juiz aceitar a resposta da máquina sem análise crítica, o que torna a supervisão humana meramente formal."},
{"id": 11875, "materia": "ia", "nivel": 3, "enunciado": "Na avaliação de modelos, a curva ROC e a área sob ela (AUC) servem para:", "opcoes": ["Medir o quanto o classificador separa as classes", "Calcular o custo de energia elétrica gasto durante todo o treinamento", "Contar o número de parâmetros do modelo", "Medir a velocidade de resposta do sistema em horário de grande movimento"], "explicacao": "Uma AUC de 0,5 equivale ao acaso; quanto mais perto de 1, melhor o modelo distingue as classes."},
{"id": 11876, "materia": "ia", "nivel": 3, "enunciado": "Em um laboratório de inovação, o teste A/B consiste em:", "opcoes": ["Comparar duas versões de uma solução com usuários reais", "Aplicar duas provas diferentes aos servidores antes de contratá-los", "Escolher entre dois fornecedores por sorteio", "Testar o sistema apenas nos dias pares e depois apenas nos dias ímpares"], "explicacao": "A comparação com dados reais ajuda a decidir com base em evidências, e não em opinião."},
{"id": 11877, "materia": "ia", "nivel": 4, "enunciado": "No aprendizado federado, o modelo é treinado:", "opcoes": ["Nos locais onde os dados estão, sem centralizá-los, trocando só atualizações", "Em um único servidor central que recebe e guarda todos os dados brutos dos usuários", "Apenas por órgãos federais do governo", "Sem nenhum dado de treinamento, apenas com regras escritas manualmente por programadores"], "explicacao": "A técnica reduz a circulação de dados pessoais, o que ajuda na privacidade, embora não elimine todos os riscos."},
{"id": 11878, "materia": "ia", "nivel": 4, "enunciado": "A privacidade diferencial protege os dados individuais:", "opcoes": ["Adicionando ruído calibrado aos resultados estatísticos", "Apagando todo o conjunto de dados logo depois de cada consulta realizada", "Exigindo senha para cada consulta ao banco", "Guardando os dados apenas em papel, em arquivos trancados e sem acesso digital"], "explicacao": "O ruído é controlado por um parâmetro que equilibra privacidade e utilidade estatística."},
{"id": 11879, "materia": "ia", "nivel": 4, "enunciado": "A destilação de conhecimento (knowledge distillation) consiste em:", "opcoes": ["Treinar um modelo menor para imitar um maior", "Apagar camadas da rede ao acaso para deixar o modelo mais rápido", "Traduzir o código do modelo para outra linguagem", "Remover todos os dados pessoais do conjunto de treinamento original"], "explicacao": "O modelo “aluno” fica mais leve e barato de rodar, preservando parte do desempenho do “professor”."},
{"id": 11880, "materia": "ia", "nivel": 4, "enunciado": "Pelo AI Act da União Europeia, a violação das práticas de IA proibidas pode gerar multa de até:", "opcoes": ["35 milhões de euros ou 7% do faturamento anual mundial, o que for maior", "1 milhão de euros, em qualquer caso", "10% do lucro do último trimestre", "100 mil euros por usuário afetado"], "explicacao": "É o teto mais alto do regulamento. As demais infrações têm limites menores."},
{"id": 11881, "materia": "ia", "nivel": 4, "enunciado": "Pela LGPD (art. 20, § 2º), se o controlador não fornecer informações sobre os critérios de uma decisão automatizada alegando segredo comercial e industrial:", "opcoes": ["A ANPD pode auditar aspectos discriminatórios", "O titular perde definitivamente o direito de pedir a revisão da decisão", "A decisão automatizada é anulada de imediato", "O controlador fica dispensado de qualquer explicação ao titular dos dados"], "explicacao": "O segredo comercial não impede a fiscalização pela autoridade nacional."},
{"id": 11882, "materia": "ia", "nivel": 4, "enunciado": "Exigir que um modelo tenha a mesma taxa de aprovação entre grupos diferentes, independentemente de outras variáveis, corresponde ao critério de justiça chamado:", "opcoes": ["Paridade demográfica", "Igualdade de oportunidades", "Calibração por grupo", "Acurácia balanceada"], "explicacao": "A igualdade de oportunidades, por outro lado, exige taxas iguais de verdadeiros positivos entre os grupos. Em geral, os critérios não podem ser satisfeitos todos ao mesmo tempo."},
{"id": 11883, "materia": "ia", "nivel": 4, "enunciado": "Na arquitetura “mistura de especialistas” (mixture of experts), o modelo:", "opcoes": ["Ativa só parte de suas sub-redes, escolhidas por um roteador", "Consulta especialistas humanos antes de gerar cada uma das respostas", "Usa um modelo diferente para cada idioma, sem roteamento", "Treina todos os parâmetros com dados fornecidos por um único especialista humano"], "explicacao": "A técnica permite modelos muito grandes com custo de processamento menor por resposta."},
